import { useHelp } from '@/hooks/useHelp';
import { Suspense, lazy } from 'react';
import { HelpSidebar } from './HelpSidebar';
import { HelpTopicCard } from './HelpTopicCard';
import { HelpStepRenderer } from './HelpStepRenderer';
import { HelpSearch } from './HelpSearch';
import { HelpFeedback } from './HelpFeedback';
import { HelpProgressBar } from './HelpProgressBar';

// Lazy-load heavy components
const HelpVideoPlayer = lazy(() => import('./HelpVideoPlayer'));
const HelpInteractiveDemo = lazy(() => import('./HelpInteractiveDemo'));

export function {{componentName}}(props: {{componentName}}Props) {
  const help = useHelp();
  return (
    <div className="help-system" data-testid="help-system">
      <HelpSidebar />
      <div className="help-content">
        <HelpSearch />
        <HelpTopicCard topic={help.currentTopic} />
        <HelpStepRenderer />
        <Suspense fallback={<div className="help-video-loading" data-testid="help-video-loading" />}>
          <HelpVideoPlayer />
        </Suspense>
        <Suspense fallback={<div className="help-demo-loading" data-testid="help-demo-loading" />}>
          <HelpInteractiveDemo />
        </Suspense>
        <HelpProgressBar />
        <HelpFeedback />
      </div>
    </div>
  );
}

