export function {{componentName}}(props: {{componentName}}Props) {
  const help = useHelp();
  const variant = props.variant ?? 'notes-all';
  const config = EMPTY_STATE_CONFIGS[variant] ?? EMPTY_STATE_CONFIGS['notes-all'];
  return (
    <div className="empty-state" data-testid="empty-state-actionable" data-variant={variant}>
      <div className="empty-illustration">{config.illustration}</div>
      <h2 className="empty-title">{config.title}</h2>
      <p className="empty-description">{config.description}</p>
      <div className="empty-actions">
        <button onClick={config.primaryAction} className="btn-primary" data-testid="empty-primary-cta">
          {config.primaryLabel}
        </button>
        {config.secondaryLabel && (
          <button onClick={config.secondaryAction} className="btn-secondary" data-testid="empty-secondary-cta">
            {config.secondaryLabel}
          </button>
        )}
      </div>
      {config.helpTopicId && (
        <button onClick={() => help.openTopic(config.helpTopicId)} className="help-link" data-testid="empty-help-link">
          Learn more
